BEGIN TRANSACTION;
CREATE TABLE "agno_runs" (run_id VARCHAR NOT NULL, session_id VARCHAR NOT NULL, run_type VARCHAR NOT NULL, agent_id VARCHAR, team_id VARCHAR, workflow_id VARCHAR, user_id VARCHAR, parent_run_id VARCHAR, status VARCHAR, run_index BIGINT, run_data JSON NOT NULL, created_at BIGINT NOT NULL, updated_at BIGINT, PRIMARY KEY (run_id), FOREIGN KEY(session_id) REFERENCES "agno_sessions" (session_id) ON DELETE CASCADE);
INSERT INTO "agno_runs" VALUES('gone','session','agent','agno',NULL,NULL,NULL,NULL,'RUNNING',0,'{"run_id": "gone", "agent_id": "agno", "created_at": 1750000000, "status": "RUNNING", "messages": []}',1750000000,1750000000);
INSERT INTO "agno_runs" VALUES('r1','session','agent','agno',NULL,NULL,NULL,NULL,'RUNNING',1,'{"run_id": "r1", "agent_id": "agno", "created_at": 1750000000, "status": "RUNNING", "messages": []}',1750000000,1750000000);
INSERT INTO "agno_runs" VALUES('r2','session','agent','agno',NULL,NULL,NULL,NULL,'RUNNING',NULL,'{"run_id": "r2", "agent_id": "agno", "created_at": 1750000000, "status": "RUNNING", "messages": []}',1750000000,1750000000);
CREATE TABLE "agno_sessions" (session_id VARCHAR NOT NULL, session_type VARCHAR NOT NULL, agent_id VARCHAR, team_id VARCHAR, workflow_id VARCHAR, user_id VARCHAR, session_data JSON, agent_data JSON, team_data JSON, workflow_data JSON, metadata JSON, summary JSON, created_at BIGINT NOT NULL, updated_at BIGINT, PRIMARY KEY (session_id));
INSERT INTO "agno_sessions" VALUES('session','agent','agno',NULL,NULL,NULL,'{"session_state": {}}',NULL,NULL,NULL,'{"mindroom_compaction": {"version": 2, "states": {"agent:agno": {"compacted_run_ids": ["gone"]}}}}','{"summary": "legacy summary"}',1750000000,1750000000);
CREATE TABLE "agno_sessions_usage" (id INTEGER PRIMARY KEY, session_id TEXT NOT NULL REFERENCES "agno_sessions"(session_id) ON DELETE CASCADE, run_id TEXT, usage_data TEXT, UNIQUE(session_id, run_id));
CREATE INDEX "idx_agno_sessions_session_type" ON "agno_sessions" (session_type);
CREATE INDEX "idx_agno_sessions_created_at" ON "agno_sessions" (created_at);
CREATE INDEX "idx_agno_runs_session_id" ON "agno_runs" (session_id);
CREATE INDEX "idx_agno_runs_run_type" ON "agno_runs" (run_type);
CREATE INDEX "idx_agno_runs_agent_id" ON "agno_runs" (agent_id);
CREATE INDEX "idx_agno_runs_team_id" ON "agno_runs" (team_id);
CREATE INDEX "idx_agno_runs_workflow_id" ON "agno_runs" (workflow_id);
CREATE INDEX "idx_agno_runs_user_id" ON "agno_runs" (user_id);
CREATE INDEX "idx_agno_runs_status" ON "agno_runs" (status);
CREATE INDEX "idx_agno_runs_created_at" ON "agno_runs" (created_at);
CREATE INDEX "idx_agno_runs_session_id_run_index" ON "agno_runs" (session_id, run_index);
COMMIT;
